) -> f64 {
    // ---- base score: remaining space ----
    let mut score = post_residual as f64;

    // ---- dead‑space penalty with aggressive scaling ----
    if next_item_size > 0 && post_residual < next_item_size {
        let remaining_ratio = (total_items - step_index) as f64 / total_items as f64;
        let size_factor = next_item_size as f64 / bin_capacity as f64;
        let penalty = 800.0
            * remaining_ratio.powf(1.3)
            * size_factor.powi(2); // heavier when next item is large
        score += penalty;
    }

    // ---- open‑bin pressure that fades non‑linearly ----
    let open_weight = 0.25
        * (1.0 - (step_index as f64 / total_items as f64))
        .max(0.15);
    score += open_bins_count as f64 * open_weight;

    // ---- mean‑residual comparison with asymmetric weighting ----
    let residual_diff = post_residual as f64 - mean_residual;
    score += if residual_diff > 0.0 {
        residual_diff * 0.7 // wasteful space
    } else {
        residual_diff * -0.6 // tighter packing
    };

    // ---- last‑chance subtlety ----
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 25.0;
    }

    // ---- new‑bin candidate adjustment ----
    if bin_residual == bin_capacity {
        let early_factor = (1.0 - (step_index as f64 / total_items as f64)).powf(2.0);
        let mut new_bin_score = -mean_residual * 0.6;
        new_bin_score += (open_bins_count as f64) * 0.35;
        new_bin_score += early_factor * 8.0;
        // Encourage new bins when average residual is very low
        if mean_residual < 0.1 * bin_capacity as f64 {
            new_bin_score -= 5.0;
        }
        score += new_bin_score;
    }

    // ---- residual‑ratio tweak ----
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio > 0.25 {
        score -= 0.4 * residual_ratio;
    } else if residual_ratio < 0.04 {
        score -= 12.0; // very tight bin
    }

    // ---- lookahead bonus for fitting next item ----
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // ---- fit‑ratio multiplier ----
    let fit_ratio = fitting_bins_count as f64 / (open_bins_count as f64 + 1.0);
    score -= 5.0 * fit_ratio.powf(1.5);

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the raw residual left after packing.
    let mut score = post_residual as f64;

    // ------------------------------------------------------------------
    // 1. Dead‑space avoidance: heavy penalty if the next item cannot fit.
    //    The penalty magnitude scales with the fraction of the bin that
    //    would be unused for the next item.
    // ------------------------------------------------------------------
    if next_item_size > 0 && post_residual < next_item_size {
        let frac = next_item_size as f64 / bin_capacity as f64;
        score += 1_000.0 * frac.max(0.1);
    }

    // ------------------------------------------------------------------
    // 2. Open‑bins pressure: discourages opening many bins, but not too
    //    harshly so that we still have options for poor fits.
    // ------------------------------------------------------------------
    score += (open_bins_count as f64) * 0.3;

    // ------------------------------------------------------------------
    // 3. Mean‑residual comparison: reward tight packing, penalise excess.
    //    The asymmetry favours leaving slightly less space than leaving
    //    a lot of space.
    // ------------------------------------------------------------------
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // ------------------------------------------------------------------
    // 4. Last‑chance penalty: if this is the only bin that can fit, we
    //    prefer it only when it leaves no space.
    // ------------------------------------------------------------------
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 50.0;
    }

    // ------------------------------------------------------------------
    // 5. New‑bin candidate: avoid opening a new bin unless the current
    //    residual situation is markedly worse than the average.
    // ------------------------------------------------------------------
    if bin_residual == bin_capacity {
        // Penalise new‑bin when many bins are already open or when the
        // mean residual is high enough to justify a fresh bin.
        let new_bin_penalty = mean_residual * 0.4
            + (open_bins_count as f64).min(10.0) * 5.0;
        score += new_bin_penalty;
    }

    // ------------------------------------------------------------------
    // 6. Late‑phase bias: as we approach the end of the stream we
    //    favour opening new bins to avoid residual waste on the last
    //    few items.
    // ------------------------------------------------------------------
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 {
            // Slightly increase score for using an existing bin in the last 20%.
            score += 200.0 * (1.0 - progress) / 0.2;
        }
    }

    // ------------------------------------------------------------------
    // 7. Item‑fit ratio: reward placing an item that almost fills the bin.
    // ------------------------------------------------------------------
    if bin_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.9 {
            score -= 10.0;
        }
    }

    // ------------------------------------------------------------------
    // 8. Fitting‑bins count: if many bins can fit the item, prefer the
    //    one with the smallest residual.
    // ------------------------------------------------------------------
    score += (fitting_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // --------- base fit score ----------
    let mut score = post_residual as f64 - (item_size as f64) * 0.018;

    // --------- residual ratio ----------
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio <= 0.05 {
        score -= 1.5 * residual_ratio;
    } else if residual_ratio <= 0.15 {
        score -= 0.8 * residual_ratio;
    } else {
        score -= 0.4 * residual_ratio;
    }
    if residual_ratio > 0.20 {
        score -= 0.4 * residual_ratio;
    }

    // --------- lookahead (one step) ----------
    let remaining_ratio = (total_items - step_index) as f64 / total_items as f64;
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= (slack as f64).powi(2) * 0.0005 * remaining_ratio.max(0.4);
    }

    // --------- overflow penalty ----------
    if next_item_size > 0 && post_residual < next_item_size {
        let penalty = 800.0 * remaining_ratio.max(0.12);
        score += penalty;
    }

    // --------- open‑bin pressure ----------
    let open_weight = 0.50 / (1.0 + 0.10 * open_bins_count as f64);
    score += (open_bins_count as f64) * open_weight;

    // --------- mean residual comparison ----------
    let residual_diff = post_residual as f64 - mean_residual;
    if residual_diff > 0.0 {
        score += residual_diff * 0.85;
    } else {
        score += residual_diff * 0.25;
    }

    // --------- single‑fit bonus ----------
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 25.0;
    }

    // --------- new‑bin candidate ----------
    if bin_residual == bin_capacity {
        let early_factor = 1.0 - (step_index as f64) / (total_items as f64);
        let mut new_bin_score = 0.0;
        new_bin_score -= mean_residual * 0.60;
        new_bin_score += (open_bins_count as f64) * 0.30;
        new_bin_score += early_factor * 8.0;
        score += new_bin_score;
    }

    // --------- high‑ratio next‑item penalty ----------
    if next_item_size > 0 {
        let ratio = next_item_size as f64 / bin_capacity as f64;
        if ratio > 0.80 {
            score -= 6.0;
        }
    }

    // --------- tight‑fit encouragement when waste is low ----------
    if mean_residual < 5.0 && residual_ratio < 0.12 {
        score -= 0.3;
    }

    score
}
